window.BOOK={"key":"mulha","app":"mutoon-mulha","lsk":"mutoon_mulha_v1","prefix":"mu_","title":"ملحة الإعراب","sub":"منظومة في النحو · القاسم بن علي الحريري (ت ٥١٦هـ) · ٣٨٠ بيتًا","poems":[{"id":"mulha","title":"ملحة الإعراب","nazim":"أبو محمد القاسم بن علي الحريري البصري","death":"ت ٥١٦هـ","meter":"الرجز","source":"المكتبة الشاملة: اللمحة في شرح الملحة لابن الصائغ، تحقيق إبراهيم بن سالم الصاعدي","srcUrl":"https://shamela.ws/book/7341","note":"الضبط من أبيات المنظومة المشكولة داخل «اللمحة في شرح الملحة» (تحقيق الصاعدي، الجامعة الإسلامية). والأبيات مرتبة على نشرة دار السلام (الشاملة 7840)، وقوبلت بها كلمةً كلمةً وبنشرة مكتبة مشكاة. وفي مواضع الخلاف اعتُمد ما يرويه المحقق في حواشيه عن «متن الملحة» و«شرح الملحة» للحريري.","verses":[["أَقُولُ مِنْ بَعْدِ افْتِتَاحِ الْقَوْلِ","بِحَمْدِ ذِي الطَّوْلِ شَدِيدِ الْحَوْلِ"],["وَبَعْدَهُ فَأَفْضَلُ السَّلاَمِ","عَلَى النَّبِيِّ سَيِّدِ الأَنَامِ"],["وَآلِهِ الأَطْهَارِ خَيْرِ آلِ","فَافْهَمْ كَلاَمِي وَاسْتَمِعْ مَقَالِي"],["يَا سَائِلِي عَنِ الْكَلاَمِ المُنْتَظِمْ","حَدًّا وَنَوْعًا وَإِلَى كَمْ يَنْقَسِمْ"],["اسْمَعْ هُدِيْتَ الرُّشْدَ مَا أَقُولُ","وَافْهَمْهُ فَهْمَ مَنْ لَهُ مَعْقُولُ"],["حَدُّ الْكَلاَمِ مَا أَفَادَ الْمُسْتَمِعْ","نَحْوُ سَعَى زَيْدٌ وَعَمْروٌ مُتَّبِعْ"],["وَنَوْعُهُ الَّذِي عَلَيْهِ يُبْنَى","اسْمٌ وَفِعْلٌ ثُمَّ حَرْفُ مَعْنَى"],["فَالاسْمُ مَا يَدْخُلُهُ مِنْ وَإِلَى","أَوْ كَانَ مَجْرُورًا بِحَتَّى وَعَلَى"],["مِثَالُهُ زَيْدٌ وَخَيْلٌ وَغَنَمْ","وَذَا وَتِلْكَ وَالَّذِيْ وَمَنْ وَكَمْ"],["وَالْفِعْلُ مَا يَدْخُلُ قَدْ وَالسِّينُ","عَلَيْهِ مِثْلُ بَانَ أَوْ يَبِينُ"],["أَوْ لَحِقَتْهُ تَاءُ مَنْ يُحَدِّثُ","كَقَوْلِهِمْ فِي لَيْسَ لَسْتُ أَنْفُثُ"],["أَوْ كَانَ أَمْراً ذَا اشْتِقَاقٍ نَحْوَ قُلْ","وَمِثْلُهُ ادْخُلْ وَانْبَسِطْ وَاشْرَبْ وَكُلْ"],["وَالْحَرْفُ مَا لَيْسَتْ لَهُ عَلاَمَهْ","فَقِسْ عَلَى قَوْلِي تَكُنْ عَلاَّمَهْ"],["مِثَالُهُ حَتَّى وَلاَ وَثُمَّا","وَهَلْ وَبَلْ وَلَوْ وَلَمْ وَلَمَّا"],["وَالاِسْمُ ضَرْبَانِ فَضَرْبٌ نَكِرَهْ","وَالآخَرُ الْمَعْرِفَةُ الْمُشْتَهِرهْ"],["فَكُلُّ مَا رُبَّ عَلَيْهِ تَدْخُلُ","فَإِنَّهُ مُنَكَّرٌ يَا رَجُلُ"],["نَحْوُ غُلاَمٍ وَكِتَابٍ وَطَبَقْ","كَقَوْلِهِمْ رُبَّ غُلاَمٍ لِي أَبَقْ"],["وَمَا عَدَا ذَلِكَ فَهْوَ مَعْرِفَهْ","لاَ يَمْتَرِيْ فِيهِ الصَّحِيْحُ الْمَعْرِفَهْ"],["مِثَالُهُ الدَّارُ وَزَيْدٌ وَأَنَا","وَذَا وَتِلْكَ وَالَّذِيْ وَذُو الْغِنَى"],["وَآلَةُ التَّعْرِيْفِ أَلْ فَمَنْ يُرِدْ","تَعْرِيفَ كَبْدٍ مُبْهَمٍ قَالَ الكَبِدْ"],["وَقَالَ قَوْمٌ إِنَّهَا اللاَّمُ فَقَطْ","إِذْ أَلِفُ الوَصْلِ مَتَى يُدْرَجْ سَقَطْ"],["وَإِنْ أَرَدْتَ قِسْمَةَ الأَفْعَالِ","لِيَنْجَلِي عَنْكَ صَدَى الإِشْكَالِ"],["فَهْيَ ثَلاَثٌ مَا لَهُنَّ رَابِعُ","مَاضٍ وَفِعْلُ الأَمْرِ وَالْمُضَارِعُ"],["فَكُلُّ مَا يَصْلُحُ فِيهِ أَمْسِ","فَإِنَّهُ مَاضٍ بِغَيْرِ لَبْسِ"],["وَحُكْمُهُ فَتْحُ الأَخِيرِ مِنْهُ","كَقَوْلِهِمْ سَارَ وَبَانَ عَنْهُ"],["وَالأَمْرُ مَبْنِيٌّ عَلَى السُّكُونِ","مِثَالُهُ احْذَرْ صَفْقَةَ الْمَغْبُونِ"],["وَإِنْ تَلاَهُ أَلِفٌ وَلاَمُ","فَاكْسِرْ وَقُلْ لِيَقُمِ الْغُلاَمُ"],["وَإِنْ أَمَرْتَ مِنْ سَعَى وَمِنْ غَدَا","فَأَسْقِطِ الْحَرْفَ الأَخِيرَ أَبَدَا"],["تَقُولُ يَا زَيْدُ اْغْدُ فِي يَوْمِ الأَحَدْ","وَاسْعَ إِلَى الْخَيْرَاتِ لُقِّيْتَ الرَّشَدْ"],["وَهَكَذَا قَوْلُكَ فِي ارْمِ مِنْ رَمَى","فَاحْذُ عَلَى ذَلِكَ فِيمَا اسْتَبْهَمَا"],["وَالأَمْرُ مِنْ خَافَ خَفِ الْعِقَابَا","وَمِنْ أَجَادَ أَجِدِ الْجَوَابَا"],["وَإِنْ يَكُنْ أَمْرُكَ لِلْمُؤَنَّثِ","فَقُلْ لَهَا خَافِي رِجَالَ الْعَبَثِ"],["وَإِنْ وَجَدْتَ هَمْزَةً أَوْ تَاءَ","أَوْ نُونَ جَمْعٍ مُخْبِرٍ أَوْ يَاءَ"],["قَدْ أُلْحِقَتْ أَوَّلَ كُلِّ فِعْلِ","فَإِنَّهُ المُضَارِعُ المُسْتَعْلِى"],["وَلَيْسَ فِي الأَفْعَالِ فِعْلٌ يُعْرَبُ","سِوَاهُ وَالتَّمْثِيلُ فِيهِ يَضْرِبُ"],["وَالأَحْرُفُ الأَرْبَعَةُ المُتَابَعَهْ","مُسَمَّيَاتٌ أَحْرُفَ المُضَارَعَهْ"],["وَسِمْطُهَا الْحَاوِي لَهَا نَأَيْتُ","فَاسْمَعْ وَعِ الْقَوْلَ كَمَا وَعَيْتُ"],["وَضَمُّهَا مِنْ أَصْلِهَا الرُّبَاعِي","مِثْلُ يُجِيْبُ مِنْ أَجَابَ الدَّاعِي"],["وَمَا سِوَاهُ فَهْيَ مِنْهُ تُفْتَتَحْ","وَلاَ تُبَلْ أَخَفَّ وَزْنٌ أَمْ رَجَحْ"],["مِثَالُهُ يَذْهَبُ زَيْدٌ وَيَجِي","وَيَسْتَجِيْشُ تَارَةً وَيَلْتَجِيِ"],["وَإِنْ تُرِدْ أَنْ تَعْرِفَ الإِعْرَابَا","لِتَقْتَفِي فِي نُطْقِكَ الصَّوَابَا"],["فَإِنَّهُ بِالرَّفْعِ ثُمَّ الْجَرِّ","وَالنَّصْبِ وَالْجَزْمِ جَمِيْعًا يَجْرِي"],["فَالرَّفْعُ وَالنَّصْبُ بِلاَ مُمَانِعِ","قَدْ دَخَلاَ فِي الاسْمِ وَالمُضَارِعِ"],["وَالْجَرُّ يَسْتَأْثِرُ بِالأَسْمَاءِ","وَالْجَزْمُ فِي الْفِعْلِ بِلاَ امْتِرَاءِ"],["فَالرَّفْعُ ضَمُّ آخِرِ الحُرُوفِ","وَالنَّصْبُ بِالْفَتْحِ بِلاَ وُقُوفِ"],["وَالْجَرُّ بِالْكَسْرَةِ لِلتَّبْيِينِ","وَالْجَزْمُ فِي السَّالِمِ بِالتَّسْكِيْنِ"],["وَنَوِّنِ الاِسْمَ الْفَرِيْدَ المُنْصَرِفْ","إِذَا دَرَجْتَ قَائِلاً وَلاَ تَقِفْ"],["وَقِفْ عَلَى المَنْصُوبِ مِنْهُ بِالأَلِفْ","كَمِثْلِ مَا تَكْتُبُهُ لاَ يَخْتَلِفْ"],["تَقُولُ عَمْرٌو قَدْ أَضَافَ زَيْدَا","وَخَالِدٌ صَادَ الغَدَاةَ صَيْدَا"],["وَتُسْقِطُ التَّنْوِينَ إِنْ أَضَفْتَهُ","أَوْ إِنْ تَكُنْ بِاللاَّمِ قَدْ عَرَّفْتَهُ"],["مِثَالُهُ جَاءَ غُلاَمُ الْوَالِي","وَأَقْبَلَ الغُلاَمُ كَالْغَزَالِ"],["وَسِتَّةٌ تَرْفَعُهَا بِالْوَاوِ","فِي قَوْلِ كُلِّ عَالِمٍ وَرَاوِي"],["وَالنَّصْبُ فِيهَا يَا أُخَيَّ بِالأَلِفْ","وَجَرُّهَا بِالْيَاءِ فَاعْرِفْ وَاعْتَرِفْ"],["وَهِيَ أَخُوكَ وَأَبُو عِمْرَانَا","وَذُو وَفُوكَ وَحَمُو عُثْمَانَا"],["ثُمَّ هَنُوكَ سَادِسُ الأَسْمَاءِ","فَاحْفَظْ مَقَالِي حِفْظَ ذِي الذَّكَاءِ"],["وَالْوَاوُ وَالْيَاءُ جَمِيعًا وَالأَلِفْ","هُنَّ حُرُوفُ الاِعْتِلاَلِ المُكْتَنِفْ"],["وَالْيَاءُ فِي الْقَاضِي وَفِي الْمُسْتَشْرِي","سَاكِنَةٌ فِي رَفْعِهَا وَالْجَرِّ"],["وَتُفْتَحُ الْيَاءُ إِذَا مَا نُصِبَا","نَحْوُ لَقِيْتُ القَاضِيَ المُهَذَّبَا"],["وَنَوِّنِ المُنَكَّرَ المَنْقُوصَا","فِي رَفْعِهِ وَجَرِّهِ خُصُوصَا"],["تَقُولُ هَذَا مُشْتَرٍ مُخَادِعُ","وَافْزَعْ إِلَى حَامٍ حِمَاهُ مَانِعُ"],["وَهَكَذَا تَفْعَلُ فِي يَاءِ الشَّجِي","وَكُلِّ يَاءٍ بَعْدَ مَكْسُورٍ تَجِي"],["هَذَا إِذَا مَا وَرَدَتْ مُخَفَّفَهْ","فَافْهَمْهُ عَنِّي فَهْمَ صَافِي المَعْرِفَهْ"],["وَلَيْسَ لِلإِعْرَابِ فِيمَا قَدْ قُصِرْ","مِنَ الأَسَامِي أَثَرٌ إِذَا ذُكِرْ"],["مِثَالُهُ يَحْيَى وَمُوسَى وَالْعَصَا","أَوْ كَحَيًا أَوْ كَرَحًى أَوْ كَحَصًى"],["فَهَذِهِ آخِرُهَا لاَ يَخْتَلِفْ","عَلَى تَصَارِيْفِ الْكَلاَمِ المُؤْتَلِفْ"],["وَرَفْعُ مَا ثَنَّيْتَهُ بِالأَلِفِ","كَقَوْلِكَ الزَّيْدَانِ كَانَا مَأْلَفِي"],["وَنَصْبُهُ وَجَرُّهُ بِالْيَاءِ","بِغَيْرِ إِشْكَالٍ وَلاَ مِرَاءِ"],["تَقُولُ زَيْدٌ لاَبِسٌ بُرْدَيْنِ","وَخَالِدٌ مُنْطَلِقُ الْيَدَيْنِ"],["وَتَلْحَقُ النُّونُ بِمَا قَدْ ثُنِّيَ","مِنَ المَفَارِيْدِ لِجَبْرِ الْوَهْنِ"],["وَكُلُّ جَمْعٍ صَحَّ فِيْهِ وَاحِدُهْ","ثُمَّ أَتَى بَعْدَ التَّنَاهِي زَائِدُهْ"],["فَرَفْعُهُ بِالْوَاوِ وَالنُّونُ تَبَعْ","مِثْلُ شَجَانِي الْخَاطِبُونَ فِي الْجُمَعْ"],["وَنَصْبُهُ وَجَرُّهُ بِالْيَاءِ","عِنْدَ جَمِيْعِ الْعَرَبِ الْعَرْبَاءِ"],["تَقُولُ حَيَّ النَّازِلِيْنَ فِي مِنَى","وَسَلْ عَنِ الزَّيْدِينَ هَلْ كَانُوا هُنَا"],["وَنُوْنُهُ مَفْتُوحَةٌ إِذْ تُذْكَرُ","وَالنُّونُ فِي كُلِّ مُثَنًّى تُكْسَرُ"],["وَتَسْقُطُ النُّونَانِ فِي الإِضَافَهْ","نَحْوُ رَأَيْتُ سَاكِنِي الرَّصَافَهْ"],["وَقَدْ لَقِيْتُ صَاحِبَيْ أَخِينَا","فَاعْلَمْهُ فِي حَذْفِهِمَا يَقِينَا"],["وَكُلُّ جَمْعٍ فِيهِ تَاءٌ زَائِدَهْ","فَارْفَعْهُ بِالضَّمِّ كَرَفْعٍ حَامِدَهْ"],["وَنَصْبُهُ وَجَرُّهُ بِالْكَسْرِ","نَحْوُ كَفَيْتُ المُسْلِمَاتِ شَرِّي"],["وَكُلُّ مَا كُسِّرَ فِي الجُمُوعِ","كَالأُسْدِ وَالأَبْيَاتِ وَالرُّبُوعِ"],["فَهْوَ نَظِيرُ الْفَرْدِ فِي الإِعْرَابِ","فَاسْمَعْ مَقَالِي وَاتَّبِعْ صَوَابِي"],["وَالجَرُّ فِي الاِسْمِ الصَّحِيْحِ المُنْصَرِفْ","بِأَحْرُفٍ هُنَّ إِذَا مَا قِيلَ صِفْ"],["مِنْ وَإِلَى وَفِي وَحَتَّى وَعَلَى","وَعَنْ وَمُنْذُ ثُمَّ حَاشَا وَخَلاَ"],["وَالْبَاءُ وَالْكَافُ إِذَا مَا زِيدَا","وَاللاَّمُ فَاحْفَظْهَا تَكُنْ رَشِيدَا"],["وَرُبَّ أَيْضًا ثُمَّ مُذْ فِيمَا حَضَرْ","مِنَ الزَّمَانِ دُوْنَ مَا مِنْهُ غَبَرْ"],["تَقُولُ مَا رَأَيْتُهُ مُذْ يَوْمِنَا","وَرُبَّ عَبْدٍ كَيِّسٍ مَرَّ بِنَا"],["وَرُبَّ تَأْتِي أَبَدًا مُصَدَّرَهْ","وَلاَ يَلِيهَا الاسْمُ إِلاَّ نَكِرَهْ"],["وَتَارَةً تُضْمَرُ بَعْدَ الْوَاوِ","كَقَولِهِمْ وَرَاكِبٍ بِجَاوِي"],["ثُمَّ تَجُرُّ الاِسْمَ بَاءُ الْقَسَمِ","وَوَاوُهُ وَالتَّاءُ أَيْضًا فَاعْلَمِ"],["لَكِنْ تُخَصُّ التَّاءُ بِاسْمِ اللهِ","إِذَا تَعَجَّبْتَ بِلاَ اشْتِبَاهِ"],["وَقَدْ يُجَرُّ الاسْمُ بِالإِضَافَهْ","كَقَوْلِهِمْ دَارُ أَبِي قُحَافَهْ"],["فَتَارَةً تَأْتِي بِمَعْنَى اللاَّمِ","نَحْوُ أَتَى عَبْدُ أَبِي تَمَّامِ"],["وَتَارَةً تَأْتِي بِمَعْنَى مِنْ إِذَا","قُلْتَ مَنَا زَيْتٍ فَقِسْ ذَاْكَ وَذَا"],["وَفِي المُضَافِ مَا يُجَرُّ أَبَدَا","مِثْلُ لَدُنْ زَيْدٍ وَإِنْ شِئْتَ لَدَى"],["وَمِنْهُ سُبْحَانَ وَذُو وَمِثْلُ","وَمَعْ وَعِنْدَ وَأُوْلُو وَكُلُّ"],["ثُمَّ الجِهَاتُ السِّتُّ فَوْقُ وَوَرَا","وَيَمْنَةً وَعَكْسُهَا بِلاَ مِرَا"],["وَهَكَذَا غَيْرُ وَبَعْضُ وَسِوَى","فِي كَلِمٍ شَتَّى رَوَاهَا مَنْ رَوَى"],["وَاجْرُرْ بِكَمْ مَا كُنْتَ عَنْهُ مُخْبِرًا","مُعَظِّمًا لِقَدْرِهِ مُكَثِّرَا"],["تَقُولُ كَمْ مَالٍ أَفَادَتْهُ يَدِي","وَكَمْ إِمَاءٍ مَلَكَتْ وَأَعْبُدِ"],["وَإِنْ فَتَحْتَ النُّطْقَ باسْمِ","مُبْتَدَا فَارْفَعْهُ وَالإِخْبَارَ عَنْهُ أَبَدَا"],["تَقُولُ مِنْ ذَلِكَ زَيْدٌ عَاقِلُ","وَالصُّلْحُ خَيْرٌ وَالأَمِيرُ عَادِلُ"],["وَلاَ يَحُوْلُ حُكْمُهُ مَتَى دَخَلْ","لَكِنْ عَلَى جُمْلَتِهِ وَهَلْ وَبَلْ"],["وَقَدِّمِ الأَخْبَارَ إِذْ تَسْتَفْهِمُ","كَقَوْلِهِمْ أَيْنَ الْكَرِيمُ المُنْعِمُ"],["وَمِثْلُهُ كَيْفَ الْمَرِيضُ المُدْنَفُ","وأَيُّهَا الْغَادِي مَتَى المُنْصَرَفُ"],["وَإِنْ يَكُنْ بَعْضُ الظُّروفِ الْخَبَرَا","فَأَوْلِهِ النَّصْبَ وَدَعْ عَنْكَ الْمِرَا"],["تَقُولُ زَيْدٌ خَلْفَ عَمْرٍو قَعَدَا","وَالصَّوْمُ يَوْمَ السَّبْتِ وَالسَّيْرُ غَدَا"],["وَإِنْ تَقُلْ أَيْنَ الأَمِيْرُ جَالِسُ","وَفِي فِنَاءِ الدَّارِ بِشْرٌ مَائِسُ"],["فَجَالِسٌ وَمَائِسٌ قَدْ رُفِعَا","وَقَدْ أُجِيزَ الرَّفْعُ وَالنَّصْبُ مَعَا"],["وَهَكَذَا إِنْ قُلْتَ زَيْدٌ لُمْتُهُ","وَخَالِدٌ ضَرَبْتُهُ وَضِمْتُهُ"],["فَالرَّفْعُ فِيهِ جَائِزٌ وَالنَّصْبُ","كِلاَهُمَا دَلَّتْ عَلَيْهِ الْكُتْبُ"],["وَكُلُّ مَا جَاءَ مِنَ الأَسْمَاءِ","عَقِيْبَ فِعْلٍ سَالِمِ الْبِنَاءِ"],["فَارْفَعْهُ إِذْ تُعْرِبُ فَهْوَ الْفَاعِلُ","نَحْوُ جَرَى الْمَاءُ وَجَارَ الْعَاذِلُ"],["وَوَحِّدِ الْفِعْلَ مَعَ الْجَمَاعَهْ","كَقَوْلِهِمْ سَارَ الرِّجَالُ السَّاعَهْ"],["وَإِنْ تَشَأْ فَزِدْ عَلَيْهِ التَّاءَ","نَحْوُ اشْتَكَتْ عُرَاتُنَا الشِّتَاءَ"],["وَتُلْحَقُ التَّاءُ عَلَى التَّحْقِيقِ","بِكُلِّ مَا تَأْنِيْثُهُ حَقِيقِي"],["كَقَوْلِهِمْ جَاءَتْ سُعَادُ ضَاحِكَهْ","وَانْطَلَقَتْ نَاقَةُ هِنْدٍ رَاتِكَهْ"],["وَتُكْسَرُ التَّاءُ بِلاَ مَحَالَهْ","فِي مِثْلِ قَدْ أَقْبَلَتِ الْغَزَالَهْ"],["وَاقْضِ قَضَاءً لاَ يُرَدُّ قَائِلُهْ","بِالرَّفْعِ فِيمَا لَمْ يُسَمَّ فَاعِلُهْ"],["مِنْ بَعْدِ ضَمِّ أَوَّلِ الأَفْعَالِ","كَقَوْلِهِمْ يُكْتَبُ عَهْدُ الْوَالِي"],["وَإِنْ يَكُنْ ثَانِي الثُّلاَثِيِّ أَلِفْ","فَاكْسِرْهُ حِينَ تَبْتَدِي وَلاَ تَقِفْ"],["تَقُولُ بِيعَ الثَّوْبُ وَالْغُلاَمُ","وَكِيْلَ زَيْتُ الشَّامِ وَالطَّعَامُ"],["وَالنَّصْبُ لِلْمَفْعُولِ حُكْمٌ وَجَبَا","كَقَوْلِهِمْ صَادَ الأَمِيرُ أَرْنَبَا"],["وَرُبَّمَا أُخِّرَ عَنْهُ الْفَاعِلُ","نَحْوُ قَدِ اسْتَوْفَى الْخَرَاجَ الْعَامِلُ"],["وَإِنْ تَقُلْ كَلَّمَ مُوسَى يَعْلَى","فَقَدِّمِ الْفَاعِلَ فَهْوَ أَوْلَى"],["وَكُلُّ فِعْلٍ مُتَعَدٍّ يَنْصِبُ","مَفْعُولَهُ مِثْلُ سَقَى وَيَشْرَبُ"],["لَكِنَّ فِعْلَ الشَّكِّ وَالْيَقِينِ","يَنْصِبُ مَفْعُولَيْنِ فِي التَّلْقِينِ"],["تَقُولُ قَدْ خِلْتُ الْهِلاَلَ لاَئِحَا","وَقَدْ وَجَدْتُ المُسْتَشَارَ نَاصِحَا"],["وَمَا أَظُنُّ عَامِرًا رَفِيقَا","وَلاَ أَرَى لِي خَالِدًا صَدِيقَا"],["وَهَكَذَا تَفْعَلُ فِي عَلِمْتُ","وَفِي حَسِبْتُ ثُمَّ فِي زَعَمْتُ"],["وَإِنْ ذَكَرْتَ فَاعِلاً مُنَوَّنَا","فَهْوَ كَمَا لَوْ كَانَ فِعْلاً بَيِّنَا"],["فَارْفَعْ بِهِ فِي لاَزِمِ الأَفْعَالِ","وَانْصِبْ إِذَا عُدِّي بِكُلِّ حَالِ"],["تَقُولُ زَيْدٌ مُشْتَرٍ أَبُوهُ","بِالرَّفْعِ مِثْلُ يَشْتَرِي أَخُوهُ"],["وَقُلْ سَعِيدٌ مُكْرِمٌ عُثْمَانَا","بِالنَّصْبِ مِثْلُ يُكْرِمُ الضِّيفَانَا"],["وَالْمَصْدَرُ الأَصْلُ وَأَيُّ أَصْلِ","وَمِنْهُ يَا صَاحِ اشْتِقَاقُ الْفِعْلِ"],["وَأَوْجَبَتْ لَهُ النُّحَاةُ النَّصْبَا","فِي قَوْلِهِمْ ضَرَبْتُ زَيْدًا ضَرْبَا"],["وَقَدْ أُقِيْمَ الْوَصْفُ وَالآلاَتُ","مَقَامَهُ وَالْعَدَدُ الإِثْبَاتُ"],["نَحْوُ ضَرَبْتُ الْعَبْدَ سَوْطًا فَهَرَبْ","وَاضْرِبْ أَشَدَّ الضَّرْبِ مَنْ يَغْشَى الرِّيَبْ"],["وَاجْلِدْهُ فِي الخَمْرِ ارْبَعِيْنَ جَلْدَهْ","وَاحْبِسْهُ مِثْلَ حَبْسِ زَيْدٍ عَبْدَهْ"],["وَرُبَّمَا أُضْمِرَ فِعْلُ الْمَصْدَرِ","كَقَوْلِهِمْ سَمْعًا وَطَوْعًا فَاخْبُرِ"],["وَمِثْلُهُ سَقْيًا لَهُ وَرَعْيَا","وَإِنْ تَشَأْ جَدْعًا لَهُ وَكَيَّا"],["وَمِنْهُ قَدْ جَاءَ الأَمِيرُ رَكْضَا","وَاشْتَمَلَ الصَّمَّاءَ إِذْ تَوَضَّا"],["وَإِنْ جَرَى نُطْقُكَ بِالْمَفْعُولِ لَهْ","فَانْصِبْهُ بِالْفِعْلِ الَّذِي قَدْ فَعَلَهْ"],["وَهْوَ لَعَمْرِي مَصْدَرٌ فِي نَفْسِهِ","لَكِنَّ جِنْسَ الْفِعْلِ غَيْرُ جِنْسِهِ"],["وَغَالِبُ الأَحْوَالِ أَنْ تَرَاهُ","جَوَابَ لِمْ فَعَلْتَ مَا تَهْوَاهُ"],["تَقُولُ قَدْ زُرْتُكَ خَوْفَ الشَّرِّ","وَغُصْتُ فِي الْبَحْرِ ابْتِغَاءَ الدُّرِّ"],["وَإِنْ أَقَمْتَ الْوَاوَ فِي الْكَلاَمِ","مُقَامَ مَعْ فَانْصِبْ بِلاَ مَلاَمِ"],["تَقُولُ جَاءَ الْبَرْدُ وَالْجِبَابَا","وَاسْتَوَتِ الْمِيَاهُ وَالأَخْشَابَا"],["وَمَا صَنَعْتَ يَا فَتَى وَسَعْدَا","فَقِسْ عَلَى هَذَا تُصَادِفْ رُشْدَا"],["وَالْحَالُ وَالتَّمْيِيزُ مَنْصُوبَانِ","عَلَى اخْتِلاَفِ الوَضْعِ وَالْمَبَانِي"],["ثُمَّ كِلاَ النَّوْعَيْنِ جَاءَ فَضْلَهْ","مُنَكَّرًا بَعْدَ تَمَامِ الجُمْلَهْ"],["لَكِنْ إِذَا نَظَرْتَ فِي اسْمِ الحَالِ","وَجَدْتَهُ اشْتُقَّ مِنَ الأَفْعَالِ"],["ثُمَّ تُرَى عِنْدَ اعْتِبَارِ مَنْ عَقَلْ","جَوَابَ كَيْفَ فِي سُؤَالِ مَنْ سَأَلْ"],["مِثَالُهُ جَاءَ الأَمِيرُ رَاكِبًا","وَقَامَ قُسٌّ فِي عُكَاظٍ خَاطِبًا"],["وَمِنْهُ مَنْ ذَا بِالْفِنَاءِ قَاعِدًا","وَبِعْتُهُ بِدِرْهَمٍ فَصَاعِدًا"],["وَإِنْ تُرِدْ مَعْرِفَةَ التّمْيِيزِ","لِكَيْ تُعَدَّ مِنْ ذَوِي التَّمْيِيزِ"],["فَهْوَ الَّذِي يُذْكَرُ بَعْدَ الْعَدَدِ","وَالْوَزْنِ وَالْكَيْلِ وَمَذْرُوعِ الْيَدِ"],["وَمَنْ إِذَا فَكَّرْتَ فِيهِ مُضْمَرَهْ","مِنْ قَبْلِ أَنْ تَذْكُرَهُ وَتُظْهِرَهْ"],["تَقُولُ عِنْدِي مَنَوانِ زُبْدَا","وَخَمْسَةٌ وَأَرْبَعُونَ عَبْدَا"],["وَقَدْ تَصَدَّقْتُ بِصَاعٍ خَلاَّ","وَمَا لَهُ غَيْرُ جَرِيبٍ نَخْلاَ"],["وَمِنْهُ أَيْضًا نِعْمَ زَيْدٌ رَجُلاَ","وَبِئْسَ عَبْدُ الدَّارِ مِنْهُ بَدَلاَ"],["وَحَبَّذَا أَرْضُ الْبَقِيْعِ أَرْضَا","وَصَالِحٌ أَطْهَرُ مِنْكَ عِرْضَا"],["وَقَدْ قَرِرْتَ بِالإِيَابِ عَيْنَا","وَطِبْتَ نَفْسًا إِذْ قَضَيْتَ الدَّيْنَا"],["وَكَمْ إِذَا جِئْتَ بِهَا مُسْتَفْهِمَا","فَانْصِبْ وَقُلْ كَمْ كَوْكَبًا تَحْوِي السَّمَا"],["وَالظَّرْفُ نَوْعَانِ فَظَرْفُ أَزْمِنَهْ","يَجْرِي مَعَ الدَّهْرِ وَظَرْفُ أَمْكِنَهْ"],["وَالْكُلُّ مَنْصُوبٌ عَلَى إِضْمَارِ فِي","فَاعْتَبِرِ الظَّرْفَ بِهَذَا وَاكْتَفِي"],["تَقُولُ صَامَ خَالِدٌ أَيَّامَا","وَغَابَ شَهْرًا وَأَقَامَ عَامَا"],["وَبَاتَ زَيْدٌ فَوْقَ سَطْحِ المَسْجِدِ","وَالْفَرَسُ الأَبْلَقُ تَحْتَ مَعْبَدِ"],["وَالرِّيحُ هَبَّتْ يَمْنَةَ المُصَلِّي","وَالزَّرْعُ تِلْقَاءَ الحَيَا المُنْهَلِّ"],["وَقِيمَةُ الفِضَّةِ دُونَ الذَّهَبِ","وَثَمَّ عَمْرٌو فَادْنُ مِنْهُ وَاقْرُبِ"],["وَدَارُهُ غَرْبِيَّ فَيْضِ البَصْرَهْ","وَنَخْلُهُ شَرْقِيَّ نَهْرِ مُرَّهْ"],["وَقَدْ أَكَلْتُ قَبْلَهُ وَبَعْدَهُ","وَإِثْرَهُ وَخَلْفَهُ وَعِنْدَهُ"],["وَعِنْدَ فِيهَا النَّصْبُ يَسْتَمِرُّ","لَكِنَّهَا بِمِنْ فَقَطْ تُجَرُّ"],["وَأَيْنَمَا صَادَفْتَ فِي لاَ تُضْمَرُ","فَارْفَعْ وَقُلْ يَومُ الْخَمِيسِ نَيِّرُ"],["وَكُلُّ مَا اسْتَثْنَيْتَهُ مِنْ مُوْجَبِ","تَمَّ الْكَلاَمُ عِنْدَهُ فَلْيُنْصَبِ"],["تَقُولُ جَاءَ الْقَوْمُ إِلاَّ سَعْدَا","وَقَامَتِ النِّسْوَةُ إِلاَّ دَعْدَا"],["وَإِنْ يَكُنْ فِيمَا سِوَى الإِيجَابِ","فَأَوْلِهِ الإِبْدَالَ فِي الإِعْرَابِ"],["تَقُولُ مَا المَفْخَرُ إِلاَّ الكَرَمُ","وَهَلْ مَحَلُّ الأَمْنِ إِلاَّ الْحَرَمُ"],["وَإِنْ تَقُلْ لاَ رَبَّ إِلاَّ اللهُ","فَارْفَعْهُ وَارْفَعْ مَا جَرَى مَجْرَاهُ"],["وَانْصِبْ إِذَا مَا قُدِّمَ المُسْتَثْنَى","تَقُولُ هَلْ إِلاَّ العِرَاقَ مَغْنَى"],["وَإِنْ تَكُنْ مُسْتَثْنِيًا بِمَا عَدَا","أَوْ مَا خَلاَ أَوْ لَيْسَ فَانْصِبْ أَبَدَا"],["تَقُولُ جَاؤوا مَا عَدَا مُحَمَّدًا","وَمَا خَلاَ عَمْرًا وَلَيْسَ أَحْمَدَا"],["وَغَيْرُ إِنْ جِئْتَ بِهَا مُسْتَثْنِيَهْ","جَرَتْ عَلَى الإِضَافَةِ المُسْتَوْلِيَهْ"],["وَرَاؤُهَا تَحْكُمُ فِي إِعْرَابِهَا","مِثْلَ اسْمِ إِلاَّ حِينَ يُسْتَثْنَى بِهَا"],["وَانْصِبْ بِلاَ فِي النَّفْيِ كُلَّ نَكِرَهْ","كَقَوْلِهِمْ لاَ شَكَّ فِيمَا ذَكَرَهْ"],["وَإِنْ بَدَا بَيْنَهُمَا مُعْتَرِضُ","فَارْفَعْ وَقُلْ لاَ لأَبِيكَ مُبْغِضُ"],["وَارْفَعْ إِذَا كَرَّرْتَ نَفْيًا وَانْصِبِ","أَوْ غَايِرِ الإِعْرَابَ فِيهِ تُصِبِ"],["تَقُولُ لاَ بَيْعٌ وَلاَ خِلاَلُ","فِيهِ وَلاَ عَيْبٌ وَلاَ إِخْلاَلُ"],["وَالرَّفْعُ فِي الثَّانِي وَفَتْحُ الأَوّلِ","قَدْ جَازَ وَالْعَكْسُ كَذَاكَ فَافْعَلِ"],["وَإِنْ تَشَأْ فَافْتَحْهُمَا جَمِيعَا","وَلاَ تَخَفْ رَدًّا وَلاَ تَقْرِيعَا"],["وَتُنْصَبُ الأَسْمَاءُ فِي التَّعَجُّبِ","نَصْبَ الْمَفَاعِيلِ فَلاَ تَسْتَعْجِبِ"],["تَقُولُ مَا أَحْسَنَ زَيْدًا إِذْ خَطَا","وَمَا أَحَدَّ سَيْفَهُ حِينَ سَطَا"],["وَإِنْ تَعَجَّبْتَ مِنَ الأَلْوَانِ","أَوْ عَاهَةٍ تَحْدُثُ فِي الأَبْدَانِ"],["فَابْنِ لَهَا فِعْلاً مِنَ الثُّلاَثِي","ثُمَّ ائْتِ بِالأَلْوَانِ وَالأَحْدَاثِ"],["تَقُولُ مَا أَنْقَى بَيَاضَ الْعَاجِ","وَمَا أَشَدَّ ظُلْمَةَ الدَّيَاجِي"],["وَالنَّصْبُ فِي الإِغْرَاءِ غَيْرُ مُلْتَبِسْ","وَهْوَ بِفِعْلٍ مُضْمَرٍ فَافْهَمْ وَقِسْ"],["تَقُولُ لِلطَّالِبِ خِلاَّ بَرَّا","دُونَكَ بِشْرًا وَعَلَيْكَ عَمْرَا"],["وَتَنْصِبُ الاسْمَ الَّذِي تُكَرِّرُهْ","عَنْ عِوَضِ الفِعْلِ الَّذِي لاَ تُظْهِرُهْ"],["مِثْلُ مَقَالِ الخَاطِبِ الأَوَّاهِ","اللَّهَ اللَّهَ عِبَادَ اللَّهِ"],["وَستَّةٌ تَنْتَصِبُ الأَسْمَاءُ","بِهَا كَمَا تَرْتَفِعُ الأَنْبَاءُ"],["وَهْيَ إِذَا رَوَيْتَ أَوْ أَمْلَيْتا","إِنَّ وَأَنَّ يَا فَتَى وَلَيْتَا"],["ثُمَّ كَأَنَّ ثُمَّ لَكِنَّ وَعَلَّ","وَاللُّغَةُ الْمَشْهُورَةُ الْفُصْحَى لَعَلَّ"],["وَإِنَّ بِالْكَسْرَةِ أُمُّ الأَحْرُفِ","تَأْتِي مَعَ الْقَوْلِ وَبَعْدَ الحَلِفِ"],["وَاللاَّمُ تَخْتَصُّ بِمَعْمُولاَتِهَا","لِيَسْتَبِينَ فَضْلُهَا فِي ذَاتِهَا"],["مِثَالُهُ إِنَّ الأَمِيرَ عَادِلُ","وَقَدْ سَمِعْتُ أَنَّ زَيْدًا رَاحِلُ"],["وَقِيلَ إِنَّ خَالِدًا لَقَادِمُ","وَإِنَّ هِنْدًا لأَبُوهَا عَالِمُ"],["وَلاَ تُقَدِّمْ خَبَرَ الْحُرُوْفِ","إِلاَّ مَعَ الْمَجْرُورِ وَالظُّرُوفِ"],["كَقَوْلِهِمْ إِنَّ لِزَيْدٍ مَالاَ","وَإِنَّ عِنْدَ عَامِرٍ جِمَالاَ"],["وَإِنْ تَزِدْ مَا بَعْدَ هَذِى الأَحْرُفِ","فَالرَّفْعُ وَالنَّصْبُ أُجِيزَ فَاعْرِفِ"],["وَالنَّصْبُ فِي لَيْتَ لَعَلَّ أَظْهَرُ","وَفِي كَأَنَّ فَاسْتَمِعْ مَا يُؤْثَرُ"],["وَعَكْسُ إِنَّ يَا أُخَيَّ فِي الْعَمَلْ","كَانَ وَمَا انْفَكَّ الْفَتَى وَلَمْ يَزَلْ"],["وَهَكَذَا أَصْبَحَ ثُمَّ أَمْسَى","وَظَلَّ ثُمَّ بَاتَ ثُمَّ أَضْحَى"],["وَصَارَ ثُمَّ لَيْسَ ثُمَّ مَا بَرِحْ","وَمَا فَتِئْ فَافْقَهْ بَيَانِي المُتَّضِحْ"],["وَأُخْتُهَا مَا دَامَ فَاحْفَظَنْهَا","وَاحْذَرْ هُدِيتَ أَنْ تَزِيغَ عَنْهَا"],["تَقُولُ قَدْ كَانَ الأَمِيرُ رَاكِبًا","وَلَمْ يَزَلْ أَبُو عَلِيٍّ غَائِبًا"],["وَأَصْبَحَ الْبَرْدُ شَدِيدًا فَاعْلَمِ","وَبَاتَ زَيْدٌ سَاهِرًا لَمْ يَنَمِ"],["وَمَنْ يُرِدْ أَنْ يَجْعَلَ الأَخْبَارَا","مُقَدَّمَاتٍ فَلْيَقُلْ مَا اخْتَارَا"],["مِثَالُهُ قَدْ كَانَ سَمْحًا وَائِلُ","وَوَاقِفًا بِالْبَابِ أَضْحَى السَّائِلُ"],["وَإِنْ تَقُلْ يَا قَوْمِ قَدْ كَانَ الْمَطَرْ","فَلَسْتَ تَحْتَاجُ لَهَا إِلَى خَبَرْ"],["وَهَكَذَا يَصْنَعُ كُلُّ مَنْ نَفَثْ","بِهَا إِذَا جَاءَتْ وَمَعْنَاهَا حَدَثْ"],["وَالْبَاءُ تَخْتَصُّ بِلَيْسَ فِي الْخَبَرْ","كَقَوْلِهِمْ لَيْسَ الْفَتَى بِالْمُحْتَقَرْ"],["وَمَا الَّتِي تَنْفِي كَلَيْسَ النَّاصِبَهْ","فِي قَوْلِ سُكَّانِ الْحِجَازِ قَاطِبَهْ"],["فَقَوْلُهُمْ مَا عَامِرٌ مُوَافِقًا","كَقَوْلِهِمْ لَيْسَ سَعِيدٌ صَادِقًا"],["وَنَادِ مَنْ تَدْعُو بِيَا أَوْ بِأَيَا","أَوْ هَمْزَةٍ أَوْ أَيْ وَإِنْ شِئْتَ هَيَا"],["وَانْصِبْ وَنَوِّنْ إِنْ تُنَادِ النَّكِرَهْ","كقولِهِمْ يَا نَهِمًا دَعِ الشَّرَهْ"],["وَإِنْ يَكُنْ مَعْرِفَةً مُشْتَهِرَهْ","فَلاَ تُنَوِّنْهُ وَضُمَّ آخِرَهْ"],["تَقُولُ يَا سَعْدُ أَيَا سَعِيدُ","وَمِثْلُهُ يَا أَيُّهَا الْعَمِيدُ"],["وَتَنْصِبُ المُضَافَ فِي النِّدَاءِ","كَقَوْلِهِمْ يَا صَاحِبَ الرِّدَاءِ"],["وَجَائِزٌ عِنْدَ ذَوِي الأَفْهَامِ","فِي يَا غُلاَمُ قَوْلُ يَا غُلاَمِي"],["وَجَوَّزُوا فَتْحَةَ هَذِي اليَاءِ","وَالْوَقْفَ بَعْدَ فَتْحِهَا بِالْهَاءِ"],["وَالْهَاءُ فِي الْوَقْفِ عَلَى غُلاَمِيَهْ","كَالْهَاءِ فِي الْوَقْفِ عَلَى سُلْطَانِيَهْ"],["وَقَالَ قَوْمٌ فِيهِ يَا غُلاَما","كَمَا تَلَوا يَا حَسْرَتَا عَلَى مَا"],["وَحَذْفُ يَا يَجُوزُ فِي النِّدَاءِ","كَقَوْلِهِمْ رَبِّ اسْتَجِبْ دُعَائِي"],["وَإِنْ تَقُلْ يَا هَذِهِ أَوْ يَا ذَا","فَحَذْفُ يَا مُمْتَنِعٌ يَا هَذَا"],["وَإِنْ تَشَأ التَّرْخِيمَ فِي حَالِ النِّدَا","فَاخْصُصْ بِهِ المَعْرِفَةَ المُنْفَرِدَا"],["وَاحْذِفْ إِذَا رَخَّمْتَ آخِرَ اسْمِهِ","وَلاَ تُغَيِّرْ مَا بَقِي عَنْ رَسْمِهِ"],["تَقُولُ يَا طَلْحَ وَيَا عَامِ اسْمَعَا","كَمَا تَقُولُ فِي سُعَادَ يَا سُعَا"],["وَقَدْ أُجِيزَ الضَّمُّ فِي التَّرْخِيمِ","فَقِيلَ يَا عَامُ بِضَمِّ المِيمِ"],["وَأَلْقِ حَرْفَينِ بِلاَ غُفُولِ","مِنْ وَزْنِ فَعْلاَنَ وَمِنْ مَفْعُولِ"],["تَقُولُ فِي مَرْوَانَ يَا مَرْوَ اجْلِسِ","وَمِثْلُهُ يَا مَنْصُ فَافْهَمْ وَقِسِ"],["وَلاَ تُرَخِّمْ هِنْدَ فِي النِّدَاءِ","وَلاَ ثُلاَثِيًّا خَلاَ مِنْ هَاءِ"],["وَإِنْ يَكُنْ آخِرَهُ هَاءٌ فَقُلْ","فِي هِبَةٍ يَا هِبَ مَنْ هَذَا الرَّجُلْ"],["وَقَوْلُهُمْ فِي صَاحِبٍ يَا صَاحِ","شَذَّ لِمَعْنًى فِيهِ بِاصْطِلاَحِ"],["وَإِنْ تُرِدْ تَصْغِيرَ الاسْمِ المُحْتَقَرْ","إِمَّا لِتِهْوَانٍ وَإِمَّا لِصِغَرْ"],["فَضُمَّ مَبْدَاهُ لِهَذِي الحَادِثَهْ","وَزِدْهُ يَاءً تَبْتَدِيهَا ثَالِثَهْ"],["تَقُولُ فِي فَلْسٍ فُلَيْسٌ يَا فَتَى","وَهَكَذَا كُلُّ ثُلاَثِيٍّ أَتَى"],["وَإِنْ يَكُنْ مُؤَنَّثًا أَرْدَفْتَهُ","هَاءً كَمَا تُلْحِقُ لَوْ وَصَفْتَهُ"],["فَصَغِّرِ النَّارَ عَلَى نُوَيْرَهْ","كَمَا تَقُولُ نَارُهُ مُنِيرَهْ"],["وَصَغِّرِ القِدْرَ فَقُلْ قُدَيْرَهْ","كَمَا تَقُولُ قِدْرُهُ كَبِيرَهْ"],["وَصَغِّرِ البَابَ فَقُلْ بُوَيْبُ","وَالنَّابُ إِنْ صَغَّرْتَهُ نُيَيْبُ"],["لأَنَّ بَابًا جَمْعُهُ أَبْوَابُ","وَالنَّابُ أَصْلُ جَمْعِهِ أَنْيَابُ"],["وَفَاعِلٌ تَصْغِيرُهُ فُوَيْعِلُ","كَقَوْلِهِمْ فِي رَاجِلٍ رُوَيْجِلُ"],["وَإِنْ تَجِدْ مِنْ بَعْدِ ثَانِيهِ أَلِفْ","فَاقْلِبْهُ يَاءً أَبَدًا وَلاَ تَقِفْ"],["تَقُولُ كَمْ غُزَيِّلٍ ذَبَحْتُ","وَكَمْ دُنَيْنِيرٍ بِهِ سَمَحْتُ"],["وَقُلْ سُرَيْحِينٌ لِسِرْحَانٍ كَمَا","تَقُولُ فِي الجَمْعِ سَرَاحِينُ الحِمَى"],["وَلاَ تُغَيِّرْ فِي عُثَيْمَانَ الأَلِفْ","وَلاَ سُكَيْرَانَ الَّذِي لاَ يَنْصَرِفْ"],["وَهَكَذَا زُعَيْفِرَانُ فَاعْتَبِرْ","بِهِ السُّدَاسِيَّاتِ وَافْقَهْ مَا ذُكِرْ"],["وَارْدُدْ إِلَى الْمَحْذُوفِ مَا كَانَ حُذِفْ","مِنْ أَصْلِهِ حَتَّى يَعُودَ مُنْتَصَفْ"],["كَقَوْلِهِمْ فِي شَفَةٍ شُفَيْهَهْ","وَالشَّاةُ إِنْ صَغَّرْتَهَا شُوَيْهَهْ"],["وَأَلْقِ فِي التَّصْغِيرِ مَا يُسْتَثْقَلُ","زَائِدُهُ أَوْ مَا تَرَاهُ يَثْقُلُ"],["وَالأَحْرُفُ اللاَّتِي تُزَادُ فِي الكَلِمْ","مَجْمُوعُهَا قَوْلُكَ يَا هَوْلُ اسْتَنِمْ"],["تَقُولُ فِي مُنْطَلِقٍ مُطَيْلِقُ","فَافْهَمْ وَفِي مُرْتَزِقٍ مُرَيْزِقُ"],["وَقِيلَ فِي سَفَرْجَلٍ سُفَيْرِجُ","وَفِي فَتًى مُسْتَخْرِجٍ مُخَيْرِجُ"],["وَقَدْ تُزَادُ اليَاءُ لِلتَّعْوِيضِ","وَالجَبْرِ لِلْمُصَغَّرِ المَهِيضِ"],["كَقَوْلِهِمْ إِنَّ المُطَيْلِيقَ أَتَى","وَاخْبَأْ السُّفَيْرِيجَ إِلَى فَصْلِ الشِّتَا"],["وَشَذَّ مِمَّا أَصَّلُوهُ ذَيَّا","تَصْغِيرُ ذَا وَمِثْلُهُ اللَّذَيَّا"],["وَقَوْلِهِمْ أَيْضًا أُنَيْسِيَانُ","شَذَّ كَمَا شَذَّ مُغَيْرِبَانُ"],["وَلَيْسَ هَذَا بِمِثَالٍ يُحْذَى","فَاتَّبِعِ الأَصْلَ وَدَعْ مَا شَذَّا"],["وَكُلُّ مَنْسُوبٍ إِلَى اسْمٍ فِي الْعَرَبْ","أَوْ بَلْدَةٍ تَلْحَقُهُ يَاءُ النَّسَبْ"],["فَشَدِّدِ اليَاءَ بِلاَ تَوَقُّفِ","مِنْ كُلِّ مَنْسُوبٍ إِلَيْهِ فَاعْرِفِ"],["تَقُولُ قَدْ جَاءَ الفَتَى البَكْرِيُّ","كَمَا تَقُولُ الحَسَنُ البَصْرِيُّ"],["وَإِنْ يَكُنْ فِي الأَصْلِ هَاءٌ فَاحْذِفِ","كَمِثْلِ مَكِّيٍّ وَهَذَا حَنَفِي"],["وَإِنْ يَكُنْ مِمَّا عَلَى وَزْنِ فَتَى","أَوْ وَزْنِ دُنْيَا أَوْ عَلَى وَزْنِ مَتَى"],["فَأَبْدِلِ الحَرْفَ الأَخِيرَ وَاوَا","وَعَاصِ مَنْ مَارَى وَدَعْ مَنْ نَاوَى"],["تَقُولُ هَذَا عَلَوِيٌّ مُعْرِقُ","وَكُلُّ لَهْوٍ دُنْيَوِيٍّ مُوْبِقُ"],["وَانْسِبْ أَخَا الْحِرْفَةِ كَالْبَقَّالِ","وَمَنْ يُضَاهِيهِ إِلَى فَعَّالِ"],["وَالْعَطْفُ وَالتَّوْكِيدُ أَيْضًا وَالبَدَلْ","تَوَابِعٌ يُعْرَبْنَ إِعْرَابَ الأُوَلْ"],["وَهَكَذَا الْوَصْفُ إِذَا ضَاهَى الصِّفَهْ","مَوْصُوفُهَا مُنَكَّرًا أَوْ مَعْرِفَهْ"],["تَقُولُ خَلِّي الْمَزْحَ وَالمُجُونَا","وَأَقْبَلَ الحُجَّاجُ أَجْمَعُونَا"],["وَامْرُرْ بِزَيْدٍ رَجُلٍ ظَرِيفِ","وَاعْطِفْ عَلَى سَائِلِكَ الضَّعِيفِ"],["وَالْعَطْفُ قَدْ يَدْخُلُ فِي الأَفْعَالِ","كَقَوْلِهِمْ ثِبْ وَاسْمُ فِي الْمَعَالِي"],["وَأَحْرُفُ الْعَطْفِ جَمِيعًا عَشَرَهْ","مَحْصُورَةٌ مَأْثُورَةٌ مُسَطَّرَهْ"],["الْوَاوُ وَالْفَاءُ وَثُمَّ لِلْمَهَلْ","وَلاَ وَحَتَّى ثُمَّ أَوْ وَأَمْ وَبَلْ"],["وَبَعْدَهَا لَكِنْ وَإِمَّا إِنْ كُسِرْ","وَجَاءَ لِلتَّخْيِيرِ فَاحْفَظْ مَا ذُكِرْ"],["هَذَا وَفِي الأَسْمَاءِ مَا لاَ يَنْصَرِفْ","فَجَرُّهُ كَنَصْبِهِ لاَ يَخْتَلِفْ"],["وَلَيْسَ لِلتَّنْوِينِ فِيهِ مَدْخَلُ","لِشِبْهِهِ الْفِعْلَ الَّذِي يُسْتَثْقَلُ"],["مِثَالُهُ أَفْعَلُ فِي الصِّفَاتِ","كَقَوْلِهِمْ أَحْمَرُ فِي الشِّيَاتِ"],["أَوْ جَاءَ فِي الْوَزْنِ مِثَالَ سَكْرَى","أَوْ وَزْنَ دُنْيَا أَوْ مِثَالَ ذِكْرَى"],["أَوْ وَزْنَ فَعْلاَنَ الَّذِي مُؤَنَّثُهْ","فَعْلَى كَسَكْرَانَ فَخُذْ مَا أَنْفُثُهْ"],["أَوْ وَزْنَ فَعْلاَءَ وَأَفْعِلاَءَ","كَمِثْلِ حَسْنَاءَ وَأَنْبِيَاءَ"],["أَوْ وَزْنَ مَثْنَى وَثُلاَثَ فِي الْعَدَدْ","إِذْ مَا رَأَى صَرْفَهُمَا قَطُّ أَحَدْ"],["وَكُلُّ جَمْعٍ بَعْدَ ثَانِيهِ أَلِفْ","وَهْوُ خُمَاسِيٌّ فَلَيْسَ يَنْصَرِفْ"],["وَهَكَذَا إِنْ زَادَ فِي المِثَالِ","نَحْوُ دَنَانِيرَ بِلاَ إِشْكَالِ"],["فَهَذِهِ الأَنْوَاعُ لَيْسَتْ تَنْصَرِفْ","فِي مَوْضِعٍ يَعْرِفُ هَذَا المُعْتَرِفْ"],["وَكُلُّ مَا تَأْنِيثُهُ بِلاَ أَلِفْ","فَهْوَ إِذَا عُرِّفَ غَيْرُ مُنْصَرِفْ"],["تَقُولُ هَذَا طَلْحَةُ الْجَوَادُ","وَهَلْ أَتَتْ زَيْنَبُ أَو سُعَادُ"],["وَإِنْ يَكُنْ مُخَفَّفا كَدَعْدِ","فَاصْرِفْهُ إِنْ شِئْتَ كَصَرْفِ سَعْدِ"],["وَأَجْرِ مَا جَاءَ بِوَزْنِ الْفِعْلِ","مُجْرَاهُ فِي الحُكْمِ بِغَيْرِ فَصْلِ"],["فَقَوْلُهُمْ أَحْمَدُ مِثْلُ أَذْهَبُ","وَقَولُهُمْ تَغْلِبُ مِثْلُ تَضْرِبُ"],["وَإِنْ عَدَلْتَ فَاعِلاً إِلَى فُعَلْ","لَمْ يَنْصَرِفْ مُعَرَّفا مِثْلُ زُحَلْ"],["وَالأَعْجَمِيُّ مِثْلُ مِيكَائِيلاَ","كَذَاكَ فِي الحُكْمِ وَإِسْمَاعِيلاَ"],["وَهَكَذَا الاِسْمَانِ حِينَ رُكِّبَا","كَقَوْلِهِمْ رَأَيْتُ مَعْدِي كَرِبَا"],["وَمِنْهُ مَا جَاءَ عَلَى فَعْلاَنا","عَلَى اخْتِلاَفِ فَائِهِ أَحْيَانا"],["تَقُولُ مَرْوَانُ أَتَى كِرْمَانا","وَرَحْمَةُ اللهِ عَلَى عُثْمَانا"],["فَهَذِهِ إِنْ عُرِّفَتْ لاَ تَنْصَرِفْ","وَمَا أَتَى مُنَكَّرًا مِنْهَا صُرِفْ"],["وَإِنْ عَرَاهَا أَلِفٌ وَلاَمُ","فَمَا عَلَى صَارِفِهَا مَلاَمُ"],["وَهَكَذَا تَصْرِفُ فِي الإِضَافَهْ","نَحْوُ سَخَا بِأَطْيَبِ الضِّيَافَهْ"],["وَلَيْسَ مَصْرُوفا مِنَ الْبِقَاعِ","إِلاَّ بِقَاعٌ جِئْنَ فِي السَّمَاعِ"],["مِثْلُ حُنَيْنٍ ومِنًى وَبَدْرِ","وَوَاسِطٍ وَدَابِقٍ وَحَجْرِ"],["وَجَائِزٌ فِي صَنْعَةِ الشِّعْرِ الصَّلِفْ","أَنْ يَصْرِفَ الشَّاعِرُ مَا لاَ يَنْصَرِفْ"],["وَإِنْ نَطَقْتَ بِالْعُقُودِ فِي الْعَدَدْ","فَانْظُرْ إِلَى الْمَعْدُودِ لُقِّيتَ الرَّشَدْ"],["فَأَثْبِتِ الْهَاءَ مَعَ الْمُذَكَّرِ","وَاحْذِفْ مَعَ الْمُؤَنَّثِ الْمُشْتَهِرِ"],["تَقُولُ لِيْ خَمْسَةُ أَثْوَابٍ جُدُدْ","وَازْمُمْ لَهُ تِسْعًا مِنَ النُّوقِ وَقُدْ"],["وَإِنْ ذَكَرْتَ الْعَدَدَ المُرَكَّبَا","وَهْوَ الَّذِي اسْتَوْجَبَ أَلاَّ يُعْرَبَا"],["فَأَلْحِقِ الْهَاءَ مَعَ المُؤَنَّثِ","بِآخِرِ الثَّانِي وَلاَ تَكْتَرِثِ"],["مِثَالُهُ عِنْدِي ثَلاَثَ عَشْرَةْ","جُمَانَةً مَنْظُومَةً وَدُرَّةْ"],["وَعَكْسُهَا يُعْمَلُ فِي التَّذْكِيرِ","بِغَيْرِ إِشْكَالٍ وَلاَ تَأْخِيرِ"],["وَقَدْ تَنَاهَى الْقَوْلُ فِي الأَسْمَاءِ","عَلَى اخْتِصَارٍ وَعَلَى اسْتِيْفَاءِ"],["وَحُقَّ أَنْ نَشْرَحَ شَرْحًا يُفْهَمُ","مَا يَنْصِبُ الْفِعْلَ وَمَا قَدْ يَجْزِمُ"],["فَيَنْصِبُ الْفِعْلَ السَّلِيمَ أَنْ وَلَنْ","وَكَيْ وَإِنْ شِئْتَ لِكَيْلاَ وَإِذَنْ"],["وَالنَّصْبُ فِي المُعْتَلِّ كَالسَّلِيمِ","فَانْصِبْهُ تَشْفِي عِلَّةَ السَّقِيمِ"],["وَاللاَّمُ حِينَ تَبْتَدِي بِالْكَسْرِ","كَمِثْلِ مَا تُكْسَرُ لاَمُ الْجَرِّ"],["وَالْفَاءُ إِنْ جَاءَتْ جَوَابَ النَّهْيِ","وَالأَمْرِ وَالْعَرْضِ مَعًا وَالنَّفْيِ"],["وَفِي جَوَابِ لَيْتَ لِي وَهَلْ فَتَى","وَأَيْنَ مَغْدَاكَ وَأَنَّى وَمَتَى"],["وَالْوَاوُ إِنْ جَاءَتْ بِمَعْنَى الْجَمْعِ","فِي طَلَبِ الْمَأْمُورِ أَوْ فِي الْمَنْعِ"],["وَيُنْصَبُ الْفِعْلُ بِأَوْ وَحَتَّى","وَكُلُّ ذَا أُودِعَ كُتْبًا شَتَّى"],["تَقُولُ أَبْغِي يَا فَتَى أَنْ تَذْهَبَا","وَلَنْ أَزَالَ قَائِمًا أَوْ تَرْكَبَا"],["وَجِئْتُ كَيْ تُولِينِيَ الْكَرَامَهْ","وَسِرْتُ حَتَّى أَدْخُلَ الْيَمَامَهْ"],["وَاقْتَبِسِ الْعِلْمَ لِكَيْمَا تُكْرَمَا","وَعَاصِ أَسْبَابَ الْهَوَى لِتَسْلَمَا"],["وَلاَ تُمَارِ جَاهِلاً فَتَتْعَبَا","وَمَا عَلَيْكَ عَتْبُهُ فَتُعْتَبَا"],["وَهَلْ صَدِيقٌ مُخْلِصٌ فَأَقْصِدَهْ","وَلَيْتَ لِي كَنْزَ الْغِنَى فَأَرْفِدَهْ"],["وَزُرْ فَتَلْتَذَّ بِأَصْنَافِ الْقِرَى","وَلاَ تُحَاضِرْ وَتُسِيءَ الْمَحْضَرَا"],["وَمَنْ يَقُلْ إِنِّي سَأَغْشَى حَرَمَكْ","فَقُلْ لَهُ إِنِّي إِذَنْ أَحْتَرِمَكْ"],["وَقُلْ لَهُ فِي الْعَرْضِ يَا هَذَا أَلاَ","تَنْزِلُ عِنْدِي فَتُصِيبَ مَأْكَلاَ"],["فَهَذِهِ نَوَاصِبُ الأَفْعَالِ","مَثَّلْتُهَا فَاحْذُ عَلَى تَمْثَالِي"],["وَإِنْ تَكُنْ خَاتِمَةُ الْفِعْلِ أَلِفْ","فَهْيَ عَلَى سُكُونِهَا لاَ تَخْتَلِفْ"],["تَقُولُ لَنْ يَرْضَى أَبُو السُّعُودِ","حَتَّى يَرَى نَتَائِجَ الْوُعُودِ"],["وَخَمْسَةٌ تَحْذِفُ مِنْهُنَّ الطَّرَفْ","فِي نَصْبِهَا فَأَلْقِهِ وَلاَ تَخَفْ"],["وَهْيَ لَقِيتَ الخَيْرَ تَفْعَلاَنِ","وَيَفْعَلاَنِ فَاعْرِفِ الْمَبَانِي"],["وَتَفْعَلُونَ ثُمَّ يَفْعَلُونَا","وَأَنْتِ يَا أَسْمَاءُ تَفْعَلِينَا"],["فَهَذِهِ تُحْذَفُ مِنْهَا النُّونُ","فِي نَصْبِهَا لِيَظْهَرَ السُّكُونُ"],["تَقُولُ لِلزَّيْدَيْنِ لَنْ تَنْطَلِقَا","وَفَرْقَدَا السَّمَاءِ لَنْ يَفْتَرِقَا"],["وَجَاهِدُوا يَا قَوْمِ حَتَّى تَغْنَمُوا","وَقَاتِلُوا الكُفَّارَ كَيْمَا يُسْلِمُوا"],["وَلَنْ يَطِيبَ العَيْشُ حَتَّى تَسْعَدِي","يَا هِنْدُ بِالْوَصْلِ الَّذِي يُرْوِي الصَّدِي"],["وَيُجْزَمُ الْفِعْلُ بِلَمْ فِي النَّفْيِ","وَاللاَّمُ فِي الأَمْرِ وَلاَ فِي النَّهْيِ"],["وَمِنْ حُرُوفِ الْجَزْمِ أَيْضًا لَمَّا","وَمَنْ يَزِدْ فِيهَا يَقُلْ أَلَمَّا"],["تَقُولُ لَمْ تَسْمَعْ كَلاَمَ مَنْ عَذَلْ","وَلاَ تُخَاصِمْ مَنْ إِذَا قَالَ فَعَلْ"],["وَخَالِدٌ لَمَّا يَرِدْ مَعْ مَنْ وَرَدْ","وَمَنْ يَوَدَّ فَلْيُوَاصِلْ مَنْ يُوَدّ"],["وَإِنْ تَلاَهُ أَلِفٌ وَلاَمُ","فَلَيْسَ غَيرُ الْكَسْرِ وَالسَّلاَمُ"],["تَقُولُ لاَ تَنْتَهِرِ الْمِسْكِينَا","وَمِثْلُهُ لَمْ يَكُنِ الَّذِيْنَا"],["وَإِنْ تَرَ المُعْتَلَّ فِيهَا رِدْفَا","أَوْ آخِرَ الْفِعْلِ فَسِمْهُ الْحَذْفَا"],["تَقُولُ لاَ تَأْسَ وَلاَ تُؤْذِ وَلاَ","تَقُلْ بِلاَ عِلْمٍ وَلاَ تَحْسُ الطِّلاَ"],["وَأَنْتَ يَا زَيْدُ فَلاَ تَهْوَ الْمُنَى","وَلاَ تَبِعْ إلاَّ بِنَقْدٍ فِي مِنَى"],["وَالْجَزْمُ فِي الْخَمْسَةِ مِثْلُ النَّصْبِ","فَاقْنَعْ بِإِيجَازِي وَقُلْ لِي حَسْبِي"],["هَذَا وَإِنْ فِي الشَّرْطِ وَالْجَزَاءِ","تَجْزِمُ فِعْلَيْنِ بِلاَ امْتِرَاءِ"],["وَتِلْوُهَا أَيٌّ وَمَنْ وَمَهْمَا","وَحَيْثُمَا أَيْضًا وَمَا وَإِذْمَا"],["وَأَيْنَ مِنْهُنَّ وَأَنَّى وَمَتَى","فَاحْفَظْ جَمِيْعَ الأَدَوَاتِ يَا فَتَى"],["وَزَادَ قَوْمٌ مَا فَقَالُوا إِمَّا","وَأَيْنَمَا كَمَا تَلَوْا أَيَّامَا"],["تَقُولُ إِنْ تَخْرُجْ تُصَادِفْ رُشْدَا","وَأَيْنَمَا تَذْهَبْ تُلاَقِ سَعْدَا"],["وَمَنْ يَزُرْ أَزُرْهُ بِاتِّفَاقِ","وَهَكَذَا تَصْنَعُ فِي البَوَاقِي"],["فَهَذِهِ جَوَازِمُ الأَفْعَالِ","جَلَوْتُهَا مَنْظُومَةَ اللَّآلِي"],["فَاحْفَظْ وُقِيْتَ السَّهْوَ مَا أَمْلَيْتُ","وَقِسْ عَلَى الْمَذْكُورِ مَا أَلْغَيْتُ"],["ثُمَّ تَعَلَّمْ أَنَّ فِي بَعْضِ الْكَلِمْ","مَا هُوَ مَبْنِيٌّ عَلَى وَضْعٍ رُسِمْ"],["فَسَكَّنُوا مَنْ إِذْ بَنَوْهَا وَأَجَلْ","وَمُذْ وَلَكِنْ وَنَعَمْ وَكَمْ وَهَلْ"],["وَضُمَّ فِي الغَايَةِ مِنْ قَبْلُ وَمِنْ","بَعْدُ وَأَمَّا بَعْدُ فَافْهَمْ وَاسْتَبِنْ"],["وَحَيْتُ ثُمَّ مُنْذُ ثُمَّ نَحْنُ","وَقَطُّ فَاحْفَظْهَا عَدَاكَ اللَّحْنُ"],["وَالْفَتْحُ فِي أَيْنَ وَأَيَّانَ وَفِي","كَيْفَ وَشَتَّانَ وَرُبَّ فَاعْرِفِ"],["وَقَدْ بَنَوْا مَا رَكَّبُوا مِنَ الْعَدَدْ","بِفَتْحِ كُلٍّ مِنْهُمَا حِينَ يُعَدّ"],["وَأَمْسِ مَبْنِيٌّ عَلَى الْكَسْرِ فَإِنْ","صُغِّرَ صَارَ مُعْرَبًا عِنْدَ الْفَطِنْ"],["وَجَيْرِ أَيْ حَقًّا وَهَؤُلاَءِ","كَأَمْسِ فِي الْكَسْرِ وَفِي الْبِنَاءِ"],["وَقِيلَ فِي الْحَرْبِ نَزَالِ مِثْلَ مَا","قَالُوا حَذَامِ وَقَطَامِ فِي الدُّمَى"],["وَقَدْ بُنِيَ يَفْعَلَنْ فِي الأَفْعَالِ","فَمَا لَهُ مُغَيِّرٌ بِحَالِ"],["تَقُولُ مِنْهُ النُّوقُ يَسْرَحْنَ وَلَمْ","يَسْرَحْنَ إِلاَّ لِلَّحَاقِ بِالنَّعَمْ"],["فَهَذِهِ أَمْثِلَةٌ مِمَّا بُنِي","جَائِلَةٌ دَائِرَةٌ فِي الأَلْسُنِ"],["وَكُلُّ مَبْنِيٍّ يَكُونُ آخِرُهْ عَلَى","سَوَاءٍ فَاسْتَمِعْ مَا أَذْكُرُهْ"],["وَقَدْ تَقَضَّتْ مُلْحَةُ الإِعْرَابِ","مُودَعَةً بَدَائِعَ الإِعْرَابِ"],["فَانْظُرْ إِلَيْهَا نَظَرَ الْمُسْتَحْسِنِ","وَأَحْسِنِ الظَّنَّ بِهَا وَحَسِّنِ"],["وَإِنْ تَجِدْ عَيْبًا فَسُدَّ الْخَلَلاَ","فَجَلَّ مَنْ لاَ فِيهِ عَيْبٌ وَعَلاَ"],["وَالْحَمْدُ لِلَّهِ عَلَى مَا أَوْلَى","فَنِعْمَ مَا أَوْلَى وَنِعْمَ الْمَوْلَى"],["ثُمَّ الصَّلاَةُ بَعْدَ حَمْدِ الصَّمَدِ","عَلَى النَّبِيِّ الْمُصْطَفَى مُحَمَّدِ"],["وَآلِهِ الأَفَاضِلِ الأَخْيَارِ","مَا انْسَلَخَ اللَّيْلُ مِنَ النَّهَارِ"],["ثُمَّ عَلَى أَصْحَابِهِ وَعِتْرَتِهْ","وَتَابِعِي مَقَالِهِ وَسُنَّتِهْ"]],"secs":{"1":"مقدمة الناظم","6":"باب تعريف الكلام","8":"باب معرفة الاسم","10":"باب معرفة الفعل","13":"باب معرفة الحرف","15":"باب النكرة والمعرفة","22":"باب قسمة الأفعال","26":"باب معرفة الأمر","33":"باب أحرف المضارعة","41":"باب معرفة الإعراب","47":"باب التنوين","52":"فصل في الأسماء الستة المعتلة المضافة","57":"فصل في الأسماء المنقوصة","63":"فصل في الأسماء المقصورة","66":"فصل في التثنية","70":"باب جمع المذكر السالم","77":"فصل في جمع التأنيث","79":"باب جمع التكسير","81":"باب حروف الجر","88":"فصل في القسم","90":"فصل في الإضافة","97":"باب كم الخبرية","99":"باب المبتدأ والخبر","108":"باب الاشتغال","110":"باب الفاعل","113":"فصل في إفراد الفعل مع الفاعل وتذكيره وتأنيثه","117":"باب المفعول الذي لم يسم فاعله","121":"باب المفعول به","124":"باب الأفعال المتعدية وهي ظننت وأخواتها","129":"باب اسم الفاعل المنون","133":"باب المصدر","141":"باب المفعول له","145":"باب المفعول معه","148":"باب الحال","154":"باب التمييز","159":"أساليب المدح والذم","162":"باب كم الاستفهامية","163":"باب الظروف","173":"باب الاستثناء","183":"باب لا في النفي","189":"باب التعجب","194":"باب الإغراء","196":"باب التحذير","198":"باب إن وأخواتها","209":"باب كان وأخواتها","220":"باب ما النافية","222":"باب النداء","233":"باب الترخيم","242":"باب التصغير","258":"باب الحروف الزوائد","267":"باب النسب","275":"باب التوابع","280":"باب العطف","283":"باب ما لا ينصرف","309":"باب العدد","317":"باب نواصب الفعل المستقبل","336":"فصل الأفعال الخمسة","343":"باب ما يجزم الفعل المضارع","353":"باب الشرط والجزاء","361":"باب المبنيات"}}],"sharh":false};
